impl BlockId {
    #[inline]
    pub const fn from_id(id: u16) -> Self {
        Self(id)
    }

    pub fn from_name(name: &str) -> Option<Self> {
        BLOCK_BY_NAME.get(name).copied().map(Self)
    }

    pub fn name(self) -> &'static str {
        BLOCK_BY_ID.get(self.0 as usize).copied().unwrap_or("minecraft:air")
    }

    #[inline]
    pub const fn id(self) -> u16 {
        self.0
    }
}
